// RSS-FEEDS LADEN & VORFILTERN
// n8n Code Node: "Run Once for All Items"
// Ziel:
// 1. RSS-Feeds laden
// 2. Direkte Aktiennews erkennen: type = stock_news
// 3. Markt-/Makro-News erkennen: type = market_news
// 4. Breitere Kandidaten erkennen: type = market_candidate
// 5. Nur eindeutig irrelevanten Unsinn ausschließen
// 6. KI bewertet später final: hoch / mittel / niedrig / irrelevant

// RSS-Quellen aus DB laden statt hartcodiert - siehe "RSS-Quellen verwalten"
// (neuer Verwaltungs-Workflow, 2026-07-26), analog zur Watchlist.
const feeds = $('RSS-Quellen aus DB laden (News)').all().map(i => ({ url: i.json.url, name: i.json.name }));

// Direkte Aktien-Watchlist, aus trading.watchlist (DB) geladen statt hartcodiert -
// siehe "Watchlist verwalten" (neuer Verwaltungs-Workflow, 2026-07-22). Patterns/
// excludePatterns werden hier aus den einfachen Keyword-Listen als Wortgrenzen-Regex
// gebaut. RWE traegt zusaetzlich einen kleinen, bewusst NICHT formularpflegbaren
// Restposten an Kontext-Regex (Verwechslung mit dem Fussballverein Rot-Weiss Essen -
// "RWE in der Naehe von Fuerth/Relegation/Fussball" laesst sich nicht als einfacher
// Ausschluss-Begriff abbilden, da es auf die Naehe zweier Woerter ankommt, nicht auf
// ein einzelnes Wort).
function escapeRegExpForWatchlist(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function toWordBoundaryRegex(phrase) { return new RegExp('\\b' + escapeRegExpForWatchlist(phrase) + '\\b', 'i'); }

const RWE_RESIDUAL_EXCLUDE_PATTERNS = [
  /\bRWE\b.*\bFürth\b/i,
  /\bRWE\b.*\bGreuther\b/i,
  /\bRelegation\b.*\bRWE\b/i,
  /\bFußball\b.*\bRWE\b/i,
  /\bFussball\b.*\bRWE\b/i
];

const watchlistRows = $('Watchlist aus DB laden (News)').all().map(i => i.json);
const watchlist = watchlistRows.map(row => ({
  ticker: row.ticker,
  name: row.name,
  patterns: (Array.isArray(row.keywords) ? row.keywords : []).map(toWordBoundaryRegex),
  excludePatterns: [
    ...(Array.isArray(row.exclude_keywords) ? row.exclude_keywords : []).map(toWordBoundaryRegex),
    ...(row.ticker === 'RWE.DE' ? RWE_RESIDUAL_EXCLUDE_PATTERNS : [])
  ]
}));

// Klare Markt-/Wirtschaftsbegriffe.
// Diese gehen als market_news durch.
const marketPatterns = [
  /\bDAX\b/i,
  /\bMDAX\b/i,
  /\bTecDAX\b/i,
  /\bEuroStoxx\b/i,
  /\bDow Jones\b/i,
  /\bNasdaq\b/i,
  /\bS&P 500\b/i,
  /\bWall Street\b/i,

  /\bMarktbericht\b/i,
  /\bBörse\b/i,
  /\bBoerse\b/i,
  /\bAktienmarkt\b/i,
  /\bFinanzmarkt\b/i,
  /\bKapitalmarkt\b/i,
  /\bAnleger\b/i,
  /\bInvestoren\b/i,
  /\bAktienkurs\b/i,
  /\bAktienkurse\b/i,

  /\bEZB\b/i,
  /\bFed\b/i,
  /\bNotenbank\b/i,
  /\bZinsen\b/i,
  /\bLeitzins\b/i,
  /\bZinserhöhung\b/i,
  /\bZinssenkung\b/i,
  /\bInflation\b/i,

  /\bKonjunktur\b/i,
  /\bWirtschaftswachstum\b/i,
  /\bRezession\b/i,
  /\bFrühjahrsgutachten\b/i,
  /\bWirtschaftsweise\b/i,
  /\bBIP\b/i,

  /\bÖlpreis\b/i,
  /\bOelpreis\b/i,
  /\bGaspreis\b/i,
  /\bEnergiepreis\b/i,
  /\bRohstoff\b/i,
  /\bRohstoffe\b/i,
  /\bSeltene Erden\b/i,

  /\bZoll\b/i,
  /\bZölle\b/i,
  /\bZoelle\b/i,
  /\bHandelskrieg\b/i,
  /\bSanktionen\b/i,
  /\bLieferkette\b/i,
  /\bLieferketten\b/i,
  /\bExport\b/i,
  /\bImport\b/i
];

// Breitere geopolitische und wirtschaftliche Kandidaten.
// Diese gehen als market_candidate durch und werden später von der KI kritisch bewertet.
const candidatePatterns = [
  /\bUSA\b/i,
  /\bUS-\b/i,
  /\bChina\b/i,
  /\bIran\b/i,
  /\bNahost\b/i,
  /\bUkraine\b/i,
  /\bRussland\b/i,
  /\bTaiwan\b/i,
  /\bEU\b/i,
  /\bEuropa\b/i,

  /\bKrieg\b/i,
  /\bKrise\b/i,
  /\bKonflikt\b/i,
  /\bEskalation\b/i,
  /\bAngriff\b/i,

  /\bIndustrie\b/i,
  /\bUnternehmen\b/i,
  /\bWirtschaft\b/i,
  /\bArbeitsplätze\b/i,
  /\bArbeitsplaetze\b/i,
  /\bJobabbau\b/i,
  /\bStandort\b/i,

  /\bKI\b/i,
  /\bKünstliche Intelligenz\b/i,
  /\bKuenstliche Intelligenz\b/i,
  /\bHalbleiter\b/i,
  /\bChip\b/i,
  /\bChips\b/i,
  /\bTechnologie\b/i
];

// Nur klar irrelevante Bereiche ausschließen.
// Nicht zu hart filtern, weil KI später bewertet.
const globalExcludePatterns = [
  /\bFußball\b/i,
  /\bFussball\b/i,
  /\bBundesliga\b/i,
  /\bChampions League\b/i,
  /\bRelegation\b/i,
  /\bTrainer\b/i,
  /\bAbwehrchef\b/i,

  /\bPromi\b/i,
  /\bReality-TV\b/i,
  /\bDschungelcamp\b/i,
  /\bTatort\b/i,
  /\bKrimi\b/i,

  /\bRezept\b/i,
  /\bKochen\b/i,
  /\bBacken\b/i,

  /\bHoroskop\b/i,
  /\bQuiz\b/i
];

// Diese Begriffe sind nicht pauschal ausgeschlossen.
// Sie werden nur ausgeschlossen, wenn kein Markt-/Wirtschaftsbezug erkennbar ist.
const softNoisePatterns = [
  /\bKonzert\b/i,
  /\bKonzerte\b/i,
  /\bMusik\b/i,
  /\bFestival\b/i,
  /\bFilm\b/i,
  /\bKino\b/i,
  /\bSport\b/i,
  /\bWahlkreis\b/i,
  /\bWahlkreiszuschnitte\b/i
];

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
  'Accept': 'application/rss+xml, application/xml, text/xml, */*'
};

function cleanText(value) {
  return String(value || '')
    .replace(/<!\[CDATA\[/g, '')
    .replace(/\]\]>/g, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#8211;/g, '–')
    .replace(/&#8212;/g, '—')
    .replace(/&#8230;/g, '…')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '”')
    .replace(/&#8216;/g, '‘')
    .replace(/&#8217;/g, '’')
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractTag(xml, tag) {
  const rx = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  return cleanText(xml.match(rx)?.[1] || '');
}

function extractLink(rawItem) {
  let link = extractTag(rawItem, 'link');

  if (!link) {
    const atomLink = rawItem.match(/<link[^>]+href=["']([^"']+)["']/i);
    if (atomLink?.[1]) {
      link = cleanText(atomLink[1]);
    }
  }

  return link;
}

function normalizeDate(datumRaw) {
  if (!datumRaw) return '';
  const d = new Date(datumRaw);
  if (isNaN(d.getTime())) return datumRaw;
  return d.toISOString();
}

function shorten(value, maxLength = 500) {
  const text = cleanText(value);
  if (text.length <= maxLength) return text;
  return text.substring(0, maxLength - 1).trim() + '…';
}

function getMatchedPattern(patterns, text) {
  for (const rx of patterns || []) {
    rx.lastIndex = 0;
    if (rx.test(text)) {
      return String(rx);
    }
  }
  return '';
}

function hasAny(patterns, text) {
  return Boolean(getMatchedPattern(patterns, text));
}

function classifyArticle(suchtext, stockMatches) {
  const hardExcluded = hasAny(globalExcludePatterns, suchtext);
  const directMarket = getMatchedPattern(marketPatterns, suchtext);
  const candidate = getMatchedPattern(candidatePatterns, suchtext);
  const softNoise = hasAny(softNoisePatterns, suchtext);

  // Direkte Aktiennews dürfen trotz weicher Noise-Wörter durch,
  // außer es ist ein harter Ausschluss.
  if (stockMatches.length > 0 && !hardExcluded) {
    return {
      allow: true,
      type: 'stock_news',
      matchGrund: stockMatches.map(m => `${m.ticker}:${m.matchGrund}`).join(', ')
    };
  }

  // Klare Marktnews gehen durch, außer harter Ausschluss.
  if (directMarket && !hardExcluded) {
    return {
      allow: true,
      type: 'market_news',
      matchGrund: directMarket
    };
  }

  // Breitere Kandidaten gehen durch,
  // aber nicht, wenn es nur weicher Lärm ohne Marktbezug ist.
  if (candidate && !hardExcluded && !softNoise) {
    return {
      allow: true,
      type: 'market_candidate',
      matchGrund: candidate
    };
  }

  return {
    allow: false,
    type: 'ignored',
    matchGrund: hardExcluded ? 'globalExclude' : (softNoise ? 'softNoiseWithoutMarketContext' : 'noMatch')
  };
}

const debugFeeds = [];
const alleArtikel = [];
const treffer = [];

for (const feed of feeds) {
  let xml = '';

  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: feed.url,
      headers,
      ignoreHttpStatusErrors: true,
      timeout: 15000
    });

    xml = typeof response === 'string'
      ? response
      : JSON.stringify(response || '');

  } catch (e) {
    debugFeeds.push({
      feed: feed.name,
      url: feed.url,
      status: 'FEHLER',
      error: e.message
    });
    continue;
  }

  const itemMatches = xml.match(/<item\b[\s\S]*?<\/item>/gi) || [];
  const entryMatches = xml.match(/<entry\b[\s\S]*?<\/entry>/gi) || [];
  const items = [...itemMatches, ...entryMatches];

  debugFeeds.push({
    feed: feed.name,
    url: feed.url,
    status: 'OK',
    xmlLength: xml.length,
    itemCount: itemMatches.length,
    entryCount: entryMatches.length
  });

  for (const rawItem of items) {
    const titel = extractTag(rawItem, 'title');

    const beschreibung =
      extractTag(rawItem, 'description') ||
      extractTag(rawItem, 'summary') ||
      extractTag(rawItem, 'content');

    const datumRaw =
      extractTag(rawItem, 'pubDate') ||
      extractTag(rawItem, 'updated') ||
      extractTag(rawItem, 'published');

    const link = extractLink(rawItem);

    if (!titel || titel.length < 5) continue;

    const artikel = {
      titel: cleanText(titel),
      beschreibung: shorten(beschreibung, 500),
      quelle: feed.name,
      datum: datumRaw,
      datum_iso: normalizeDate(datumRaw),
      link
    };

    alleArtikel.push(artikel);

    const suchtext = `${artikel.titel} ${artikel.beschreibung}`;

    // Direkte Aktienmatches sammeln
    const stockMatches = [];

    for (const aktie of watchlist) {
      const matchedPattern = getMatchedPattern(aktie.patterns, suchtext);
      const excludedPattern = getMatchedPattern(aktie.excludePatterns || [], suchtext);

      if (matchedPattern && !excludedPattern) {
        stockMatches.push({
          ticker: aktie.ticker,
          name: aktie.name,
          matchGrund: matchedPattern
        });
      }
    }

    const classification = classifyArticle(suchtext, stockMatches);

    if (!classification.allow) {
      continue;
    }

    // Wenn direkte Aktienmatches vorhanden sind: pro Aktie ein eigenes Item ausgeben
    if (stockMatches.length > 0) {
      for (const match of stockMatches) {
        treffer.push({
          json: {
            type: 'stock_news',
            ticker: match.ticker,
            name: match.name,
            titel: artikel.titel,
            beschreibung: artikel.beschreibung,
            quelle: artikel.quelle,
            datum: artikel.datum,
            datum_iso: artikel.datum_iso,
            link: artikel.link,
            matchGrund: match.matchGrund,
            vorfilter: 'direkter_aktienbezug',
            zeitstempel: new Date().toISOString()
          }
        });
      }

      continue;
    }

    // Sonst allgemeine Marktnews oder Kandidaten ausgeben
    treffer.push({
      json: {
        type: classification.type,
        ticker: 'MARKT',
        name: classification.type === 'market_news'
          ? 'Allgemeine Marktlage'
          : 'Markt-Kandidat zur KI-Prüfung',
        titel: artikel.titel,
        beschreibung: artikel.beschreibung,
        quelle: artikel.quelle,
        datum: artikel.datum,
        datum_iso: artikel.datum_iso,
        link: artikel.link,
        matchGrund: classification.matchGrund,
        vorfilter: classification.type === 'market_news'
          ? 'klarer_marktbezug'
          : 'breiter_kandidat',
        zeitstempel: new Date().toISOString()
      }
    });
  }
}

// Duplikate entfernen.
// Wichtig: Quelle nicht mehr in den Key, damit Tagesschau + Tagesschau Wirtschaft nicht doppelt bleiben.
const seen = new Set();

const unique = treffer.filter(e => {
  const key = [
    e.json.type,
    e.json.ticker,
    e.json.link || e.json.titel.substring(0, 120)
  ].join('|');

  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Sortierung: stock_news zuerst, dann market_news, dann market_candidate, jeweils neueste zuerst
unique.sort((a, b) => {
  const typeScore = {
    stock_news: 1,
    market_news: 2,
    market_candidate: 3
  };

  const ta = typeScore[a.json.type] || 9;
  const tb = typeScore[b.json.type] || 9;

  if (ta !== tb) return ta - tb;

  const da = new Date(a.json.datum_iso || 0).getTime();
  const db = new Date(b.json.datum_iso || 0).getTime();

  return db - da;
});


// RSS-Status ermitteln
const feedsOk     = debugFeeds.filter(f => f.status === 'OK').length;
const feedsFehler = debugFeeds.filter(f => f.status === 'FEHLER').length;

const rss_status =
  feedsOk === 0                      ? 'komplett_fehler' :
  feedsFehler > 0                    ? 'teilweise_fehler' :
                                       'ok';

// Treffer vorhanden: direkt zurückgeben (keine seenNewsLinks-Filterung mehr)
if (unique.length > 0) {
  return unique;
}

// Keine Treffer: Debug-Item mit rss_status
return [
  {
    json: {
      rss_status:      rss_status === 'komplett_fehler' ? 'komplett_fehler' : 'keine_treffer',
      info:            'Keine relevanten Aktien-, Markt- oder Kandidaten-Nachrichten gefunden',
      feedsOk,
      feedsFehler,
      feedsGetestet:   feeds.length,
      feedsDebug:      debugFeeds,
      artikelGesamt:   alleArtikel.length,
      zeitstempel:     new Date().toISOString()
    }
  }
];

// RSS-FEED FEHLER-CHECK
// Prüft ob das Item ein reines Debug-Item ohne Nachrichten ist
// (passiert wenn alle Feeds fehlschlagen)

const j = $json;

// Wenn kein titel vorhanden aber 'info'-Feld → alle Feeds fehlgeschlagen
const alleFeedsFehler =
  !j.titel &&
  j.info &&
  Array.isArray(j.feedsDebug) &&
  j.feedsDebug.every(f => f.status === 'FEHLER');

if (alleFeedsFehler) {
  // Static Data für Fehler-Matrix nutzen
  const sd = $getWorkflowStaticData('global');
  sd.rss_alle_feeds_fehler = true;
  sd.rss_fehler_zeitstempel = new Date().toISOString();
  sd.rss_fehler_feeds = j.feedsDebug;
}

return { json: { ...j, _rss_alle_fehler: alleFeedsFehler } };

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

function normalizeTitle(raw) {
  return String(raw || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .toLowerCase()
    .replace(/[^a-z0-9äöüß\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 160);
}

// FIX 2026-08-01 (Fehleranalyse D9, hoch): news_key nutzte bisher den rohen,
// unveraenderten Link - zwei Tracking-URLs desselben Artikels (z.B. mit/ohne
// utm_source, http vs. https, mit/ohne Trailing-Slash) erzeugten zwei
// verschiedene Keys und liefen am exakten Duplikat-Check vorbei (blieben nur
// noch vom Jaccard-Titel-Vergleich abhaengig). Manuelle URL-Kanonisierung
// statt new URL() - im n8n-Code-Node-Sandbox dieser Instanz nicht verfuegbar
// (siehe RSS-Quellen verwalten, A11-Fix, gleiche Erkenntnis).
function canonicalizeUrl(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  const m = s.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?/);
  if (!m) return s.toLowerCase();
  const protocol = m[1].toLowerCase();
  const host = m[2].toLowerCase();
  let path = m[3] || '';
  const query = m[4] || '';

  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);

  const TRACKING_PARAM = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ref_src|ref|igshid|spm|_ga|mkt_tok)/i;
  const keptParams = [];
  if (query) {
    for (const pair of query.split('&')) {
      if (!pair) continue;
      const key = pair.split('=')[0];
      if (!TRACKING_PARAM.test(key || '')) keptParams.push(pair);
    }
  }
  keptParams.sort();
  const qs = keptParams.length ? '?' + keptParams.join('&') : '';
  return protocol + '://' + host + path + qs;
}

// content_hash (D9): einfacher, deterministischer 32-Bit-Hash (djb2) statt
// crypto - Node-Builtins sind im Sandbox nicht garantiert verfuegbar (siehe
// new URL()-Erfahrung oben), und fuer einen Dedup-Fingerprint reicht ein
// nicht-kryptographischer Hash voellig aus (Verteidigung in der Tiefe neben
// dem bestehenden Exact-Match + Jaccard-Titel-Vergleich, nicht die einzige
// Verteidigungslinie).
function contentHash(text) {
  const s = String(text || '');
  let h = 5381;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}
function normalizeForHash(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/[^a-z0-9äöüß\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const heute = getBusinessDate();
const linkRoh = ($json.link || '').trim();
const link = canonicalizeUrl(linkRoh);
const quelle = ($json.quelle || 'unbekannt').trim();
const titel  = $json.titel || '';
const beschreibung = $json.beschreibung || '';

const news_key = link
  ? `${heute}|${link}`
  : `${heute}|${quelle}|${normalizeTitle(titel)}`;

const content_hash = contentHash(normalizeForHash(titel + '|' + beschreibung));

return {
  json: {
    ...$json,
    news_key,
    content_hash
  }
};

// Reduziert beliebig viele Input-Items auf genau 1 Item, damit die
// nachfolgenden Postgres-Abfragen nicht pro News-Item, sondern einmal
// pro Lauf ausgefuehrt werden (gleiches Prinzip wie im Original 'Dedup:
// DB-Lesen einmal starten').
return [{ json: { _trigger: true } }];

const rows = $input.all().map(i => i.json || {});
return [{ json: {
  known_keys: rows.flatMap(r => [r.news_key, r.link].filter(Boolean)),
  known_titles: rows.map(r => r.titel).filter(Boolean),
  // FIX 2026-08-01 (Fehleranalyse D9): dritte Dedup-Schicht neben Exact-Key/
  // Link-Match und Jaccard-Titel-Aehnlichkeit.
  known_content_hashes: rows.map(r => r.content_hash).filter(Boolean)
} }];

// NEWS-DUPLIKAT-CHECK – Run Once for All Items
// Prüft: 1) Exakter Key/Link-Match (auf kanonisierten URLs, siehe D9)
//         2) content_hash-Match (D9) - exakter Titel+Beschreibung-Fingerprint
//         3) Titel-Ähnlichkeit (Jaccard) gegen bekannte + aktuelle Titel
//
// FIX 2026-08-02 (Fehleranalyse D10, mittel): Duplikate wurden bisher per
// "continue" komplett verworfen - eine Agenturmeldung/aktualisierte Fassung
// desselben Artikels aktualisierte last_seen_at der Original-Zeile nie,
// obwohl die Spalte genau dafuer angelegt ist (sql/009). Duplikate werden
// jetzt NICHT mehr verworfen, sondern mit _isDuplicate:true + einem
// verlaesslichen Match-Schluessel (news_key/link/content_hash) ausgegeben -
// "IF: News neu?" (bestehende Bedingung _isDuplicate===false) leitet sie in
// einen neuen Zweig, der NUR bei einem eindeutigen Schluessel (exakter Key/
// Link/content_hash) last_seen_at aktualisiert. Ein reiner Jaccard-Titel-
// Treffer hat keinen eindeutigen DB-Schluessel (Titel sind nicht unique) und
// wird bewusst NICHT geschrieben - lieber kein Update als ein falsch
// zugeordnetes.

const items = $input.all();

let knownKeysArray = [];
let knownTitlesArray = [];
let knownContentHashesArray = [];
const newsItems = [];

for (const item of items) {
  const j = item.json || {};
  if (Array.isArray(j.known_keys)) {
    knownKeysArray = j.known_keys;
    if (Array.isArray(j.known_titles)) {
      knownTitlesArray = j.known_titles;
    }
    if (Array.isArray(j.known_content_hashes)) {
      knownContentHashesArray = j.known_content_hashes;
    }
  } else if (j.news_key || j.titel || j.link) {
    newsItems.push(j);
  }
}

const knownKeys = new Set(
  knownKeysArray.filter(Boolean).map(k => String(k).trim())
);
const knownContentHashes = new Set(
  knownContentHashesArray.filter(Boolean).map(h => String(h).trim())
);

// Bekannte Titel direkt aus der DB (titel-Spalte) statt aus dem Key-Format geraten –
// vorher wurden Titel nur aus dem "kein Link"-Key-Format (3 Teile) extrahiert, das
// bei Artikeln mit Link (fast immer) nie zutraf → History-Vergleich lief faktisch leer.
const knownTitles = knownTitlesArray.filter(Boolean).map(t => String(t).trim());

// ── Hilfsfunktionen Ähnlichkeit ────────────────────────────────────────────────
function normalizeForSim(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9äöüß\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(text) {
  return new Set(normalizeForSim(text).split(' ').filter(w => w.length > 2));
}

function jaccardSimilarity(titleA, titleB) {
  const setA = tokenize(titleA);
  const setB = tokenize(titleB);
  if (setA.size === 0 && setB.size === 0) return 1;
  if (setA.size === 0 || setB.size === 0) return 0;

  let intersection = 0;
  for (const word of setA) {
    if (setB.has(word)) intersection++;
  }
  const union = setA.size + setB.size - intersection;
  return intersection / union;
}

// Schwellenwert: 0.6 = 60% Wort-Überlappung → als Duplikat werten
// (Tagesschau + Tagesschau Wirtschaft haben oft identische Titel → ~1.0)
// Kannst du auf 0.5 senken für aggressivere Deduplizierung
const SIMILARITY_THRESHOLD = 0.6;

// ── Duplikat-Check ─────────────────────────────────────────────────────────────
const seenThisRun = new Set();
const seenContentHashesThisRun = new Set();
const seenTitlesThisRun = [];  // Array für Ähnlichkeitsvergleich innerhalb des Runs
const output = [];

for (const j of newsItems) {
  const key  = String(j.news_key || '').trim();
  const link = String(j.link     || '').trim();
  const titel = String(j.titel   || '').trim();
  const contentHash = String(j.content_hash || '').trim();

  // 1) Exakter Key/Link-Check (Link seit D9 bereits kanonisiert in "News: news_key erzeugen")
  const matchedKey = (key && (knownKeys.has(key) || seenThisRun.has(key))) ? key : null;
  const matchedLink = (!matchedKey && link && (knownKeys.has(link) || seenThisRun.has(link))) ? link : null;

  if (matchedKey || matchedLink) {
    output.push({ json: { ...j, _isDuplicate: true, dedup_status: 'duplicate', dedup_reason: 'exact_key_or_link', match_news_key: matchedKey, match_link: matchedLink } });
    continue;
  }

  // 2) content_hash-Check - derselbe Titel+Beschreibung-Inhalt unter
  // einem voellig anderen Link (z.B. Kurz-URL vs. Volltext-URL derselben Meldung).
  const isContentHashDuplicate =
    contentHash && (knownContentHashes.has(contentHash) || seenContentHashesThisRun.has(contentHash));

  if (isContentHashDuplicate) {
    output.push({ json: { ...j, _isDuplicate: true, dedup_status: 'duplicate', dedup_reason: 'content_hash', match_content_hash: contentHash } });
    continue;
  }

  // 3) Titel-Ähnlichkeits-Check
  let isSimilarDuplicate = false;

  // Gegen bekannte Titel aus DB
  for (const knownTitle of knownTitles) {
    if (jaccardSimilarity(titel, knownTitle) >= SIMILARITY_THRESHOLD) { isSimilarDuplicate = true; break; }
  }

  // Gegen bereits akzeptierte Artikel in diesem Run
  if (!isSimilarDuplicate) {
    for (const seenTitle of seenTitlesThisRun) {
      if (jaccardSimilarity(titel, seenTitle) >= SIMILARITY_THRESHOLD) { isSimilarDuplicate = true; break; }
    }
  }

  if (isSimilarDuplicate) {
    // Kein eindeutiger DB-Schluessel fuer einen reinen Titel-Treffer (Titel
    // sind nicht unique) - last_seen_at wird hier bewusst NICHT aktualisiert,
    // nur als Duplikat markiert/verworfen (unveraendertes bisheriges Verhalten
    // fuer diesen speziellen Fall).
    output.push({ json: { ...j, _isDuplicate: true, dedup_status: 'duplicate', dedup_reason: 'jaccard_title' } });
    continue;
  }

  // Neu und einzigartig → durchlassen
  if (key)  seenThisRun.add(key);
  if (link) seenThisRun.add(link);
  if (contentHash) seenContentHashesThisRun.add(contentHash);
  seenTitlesThisRun.push(normalizeForSim(titel));

  output.push({
    json: {
      ...j,
      _isDuplicate: false,
      dedup_status: 'new'
    }
  });
}

return output;

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJson(v) { return `'` + JSON.stringify(v === undefined ? null : v).replace(/'/g, `''`) + `'::jsonb`; }
function pgArr(v) { return `'{` + (Array.isArray(v) ? v : []).map(x => String(x).replace(/"/g,'\\"')).join(',') + `}'`; }


const j = $json;
// FIX 2026-08-01 (Fehleranalyse D5, kritisch): die INSERT-Spaltenliste beschraenkte sich
// bisher auf news_key/title/url/source/published_at/status - der Vorfilter-Node
// ("RSS-Feeds laden & filtern") liefert description/type/matchGrund/ticker aber bereits
