// Ausschluss-Begriff abbilden, da es auf die Naehe zweier Woerter ankommt, nicht auf
// ein einzelnes Wort).
function escapeRegExpForWatchlist(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function toWordBoundaryRegex(phrase) { return new RegExp('\\b' + escapeRegExpForWatchlist(phrase) + '\\b', 'i'); }

