function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

function normalizeTitle(raw) {
  return String(raw || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .toLowerCase()
    .replace(/[^a-z0-9äöüß\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 160);
}

// FIX 2026-08-01 (Fehleranalyse D9, hoch): news_key nutzte bisher den rohen,
// unveraenderten Link - zwei Tracking-URLs desselben Artikels (z.B. mit/ohne
// utm_source, http vs. https, mit/ohne Trailing-Slash) erzeugten zwei
// verschiedene Keys und liefen am exakten Duplikat-Check vorbei (blieben nur
// noch vom Jaccard-Titel-Vergleich abhaengig). Manuelle URL-Kanonisierung
// statt new URL() - im n8n-Code-Node-Sandbox dieser Instanz nicht verfuegbar
// (siehe RSS-Quellen verwalten, A11-Fix, gleiche Erkenntnis).
function canonicalizeUrl(raw) {
  const s = String(raw || '').trim();
  if (!s) return '';
  const m = s.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?/);
  if (!m) return s.toLowerCase();
  const protocol = m[1].toLowerCase();
  const host = m[2].toLowerCase();
  let path = m[3] || '';
  const query = m[4] || '';

  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);

  const TRACKING_PARAM = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ref_src|ref|igshid|spm|_ga|mkt_tok)/i;
  const keptParams = [];
  if (query) {
    for (const pair of query.split('&')) {
      if (!pair) continue;
      const key = pair.split('=')[0];
      if (!TRACKING_PARAM.test(key || '')) keptParams.push(pair);
    }
  }
  keptParams.sort();
  const qs = keptParams.length ? '?' + keptParams.join('&') : '';
  return protocol + '://' + host + path + qs;
}

// content_hash (D9): einfacher, deterministischer 32-Bit-Hash (djb2) statt
// crypto - Node-Builtins sind im Sandbox nicht garantiert verfuegbar (siehe
// new URL()-Erfahrung oben), und fuer einen Dedup-Fingerprint reicht ein
// nicht-kryptographischer Hash voellig aus (Verteidigung in der Tiefe neben
// dem bestehenden Exact-Match + Jaccard-Titel-Vergleich, nicht die einzige
// Verteidigungslinie).
function contentHash(text) {
  const s = String(text || '');
  let h = 5381;
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}
function normalizeForHash(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/[^a-z0-9äöüß\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const heute = getBusinessDate();
const linkRoh = ($json.link || '').trim();
const link = canonicalizeUrl(linkRoh);
const quelle = ($json.quelle || 'unbekannt').trim();
const titel  = $json.titel || '';
const beschreibung = $json.beschreibung || '';

const news_key = link
  ? `${heute}|${link}`
  : `${heute}|${quelle}|${normalizeTitle(titel)}`;

const content_hash = contentHash(normalizeForHash(titel + '|' + beschreibung));

return {
  json: {
    ...$json,
    news_key,
    content_hash
  }
};

// Reduziert beliebig viele Input-Items auf genau 1 Item, damit die
// nachfolgenden Postgres-Abfragen nicht pro News-Item, sondern einmal
// pro Lauf ausgefuehrt werden (gleiches Prinzip wie im Original 'Dedup:
// DB-Lesen einmal starten').
return [{ json: { _trigger: true } }];

const rows = $input.all().map(i => i.json || {});
return [{ json: {
  known_keys: rows.flatMap(r => [r.news_key, r.link].filter(Boolean)),
  known_titles: rows.map(r => r.titel).filter(Boolean),
  // FIX 2026-08-01 (Fehleranalyse D9): dritte Dedup-Schicht neben Exact-Key/
  // Link-Match und Jaccard-Titel-Aehnlichkeit.
  known_content_hashes: rows.map(r => r.content_hash).filter(Boolean)
} }];

// NEWS-DUPLIKAT-CHECK – Run Once for All Items
// Prüft: 1) Exakter Key/Link-Match (wie bisher, jetzt auf kanonisierten URLs, siehe D9)
//         2) content_hash-Match (NEU, D9) - exakter Titel+Beschreibung-Fingerprint,
//            faengt Faelle ab, die trotz kanonisierter URL noch unter zwei
//            verschiedenen Links laufen (z.B. eine Kurz- und eine Volltext-URL)
//         3) Titel-Ähnlichkeit (Jaccard) gegen bekannte + aktuelle Titel

const items = $input.all();

let knownKeysArray = [];
let knownTitlesArray = [];
let knownContentHashesArray = [];
const newsItems = [];

for (const item of items) {
  const j = item.json || {};
  if (Array.isArray(j.known_keys)) {
    knownKeysArray = j.known_keys;
    if (Array.isArray(j.known_titles)) {
      knownTitlesArray = j.known_titles;
    }
    if (Array.isArray(j.known_content_hashes)) {
      knownContentHashesArray = j.known_content_hashes;
    }
  } else if (j.news_key || j.titel || j.link) {
    newsItems.push(j);
  }
}

const knownKeys = new Set(
  knownKeysArray.filter(Boolean).map(k => String(k).trim())
);
const knownContentHashes = new Set(
  knownContentHashesArray.filter(Boolean).map(h => String(h).trim())
);

// Bekannte Titel direkt aus der DB (titel-Spalte) statt aus dem Key-Format geraten –
// vorher wurden Titel nur aus dem "kein Link"-Key-Format (3 Teile) extrahiert, das
// bei Artikeln mit Link (fast immer) nie zutraf → History-Vergleich lief faktisch leer.
const knownTitles = knownTitlesArray.filter(Boolean).map(t => String(t).trim());

// ── Hilfsfunktionen Ähnlichkeit ────────────────────────────────────────────────
function normalizeForSim(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9äöüß\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(text) {
  return new Set(normalizeForSim(text).split(' ').filter(w => w.length > 2));
}

function jaccardSimilarity(titleA, titleB) {
  const setA = tokenize(titleA);
  const setB = tokenize(titleB);
  if (setA.size === 0 && setB.size === 0) return 1;
  if (setA.size === 0 || setB.size === 0) return 0;

  let intersection = 0;
  for (const word of setA) {
    if (setB.has(word)) intersection++;
  }
  const union = setA.size + setB.size - intersection;
  return intersection / union;
}

// Schwellenwert: 0.6 = 60% Wort-Überlappung → als Duplikat werten
// (Tagesschau + Tagesschau Wirtschaft haben oft identische Titel → ~1.0)
// Kannst du auf 0.5 senken für aggressivere Deduplizierung
const SIMILARITY_THRESHOLD = 0.6;

// ── Duplikat-Check ─────────────────────────────────────────────────────────────
const seenThisRun = new Set();
const seenContentHashesThisRun = new Set();
const seenTitlesThisRun = [];  // Array für Ähnlichkeitsvergleich innerhalb des Runs
const output = [];

for (const j of newsItems) {
  const key  = String(j.news_key || '').trim();
  const link = String(j.link     || '').trim();
  const titel = String(j.titel   || '').trim();
  const contentHash = String(j.content_hash || '').trim();

  // 1) Exakter Key/Link-Check (Link seit D9 bereits kanonisiert in "News: news_key erzeugen")
  const isExactDuplicate =
    (key  && (knownKeys.has(key)  || seenThisRun.has(key)))  ||
    (link && (knownKeys.has(link) || seenThisRun.has(link)));

  if (isExactDuplicate) continue;

  // 2) NEU (D9): content_hash-Check - derselbe Titel+Beschreibung-Inhalt unter
  // einem voellig anderen Link (z.B. Kurz-URL vs. Volltext-URL derselben Meldung).
  const isContentHashDuplicate =
    contentHash && (knownContentHashes.has(contentHash) || seenContentHashesThisRun.has(contentHash));

  if (isContentHashDuplicate) continue;

  // 3) Titel-Ähnlichkeits-Check
  let isSimilarDuplicate = false;
  let similarScore = 0;

  // Gegen bekannte Titel aus DB
  for (const knownTitle of knownTitles) {
    const sim = jaccardSimilarity(titel, knownTitle);
    if (sim >= SIMILARITY_THRESHOLD) {
      isSimilarDuplicate = true;
      similarScore = sim;
      break;
    }
  }

  // Gegen bereits akzeptierte Artikel in diesem Run
  if (!isSimilarDuplicate) {
    for (const seenTitle of seenTitlesThisRun) {
      const sim = jaccardSimilarity(titel, seenTitle);
      if (sim >= SIMILARITY_THRESHOLD) {
        isSimilarDuplicate = true;
        similarScore = sim;
        break;
      }
    }
  }

  if (isSimilarDuplicate) continue;

  // Neu und einzigartig → durchlassen
  if (key)  seenThisRun.add(key);
  if (link) seenThisRun.add(link);
  if (contentHash) seenContentHashesThisRun.add(contentHash);
  seenTitlesThisRun.push(normalizeForSim(titel));

  output.push({
    json: {
      ...j,
      _isDuplicate: false,
      dedup_status: 'new'
    }
  });
}

return output;

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJson(v) { return `'` + JSON.stringify(v === undefined ? null : v).replace(/'/g, `''`) + `'::jsonb`; }
function pgArr(v) { return `'{` + (Array.isArray(v) ? v : []).map(x => String(x).replace(/"/g,'\\"')).join(',') + `}'`; }


const j = $json;
// FIX 2026-08-01 (Fehleranalyse D5, kritisch): die INSERT-Spaltenliste beschraenkte sich
// bisher auf news_key/title/url/source/published_at/status - der Vorfilter-Node
// ("RSS-Feeds laden & filtern") liefert description/type/matchGrund/ticker aber bereits
// fertig aufbereitet mit (sql/009 legt die Spalten dafuer seit Paket 1 an). Diese Werte
// gingen bisher spurlos verloren, bevor die KI ueberhaupt beteiligt war.
// Zusaetzlich (Teil von D5): ein Artikel mit mehreren Ticker-Treffern erzeugt pro Ticker ein
// eigenes Item mit identischem news_key - vorher liess ON CONFLICT DO NOTHING das zweite
// INSERT leerlaufen, der zweite Tickerbezug ging unwiederbringlich verloren. Jetzt
// ON CONFLICT DO UPDATE, das preclassified_tickers um den neuen Ticker ergaenzt (dedupliziert)
// statt das gesamte zweite INSERT zu verwerfen.
// FIX 2026-08-01 (Fehleranalyse D9, hoch): content_hash (seit sql/009 angelegt, bis dahin nie
// befuellt) wird jetzt aus "News: news_key erzeugen" mitgefuehrt und persistiert - dient dort
// bereits als dritte Dedup-Schicht, macht denselben Fingerprint jetzt auch nachtraeglich per
// SQL abfragbar. url bleibt bewusst der ORIGINALE (nicht kanonisierte) Link - die
// Kanonisierung ist nur ein Dedup-Hilfsmittel fuer news_key, kein Ersatz fuer den echten,
// klickbaren Quelllink.
const tickerArr = j.ticker ? [String(j.ticker)] : [];
const sql = `INSERT INTO trading.news_items
  (news_key, title, url, source, published_at, status, description, preclassified_type, match_reason, preclassified_tickers, content_hash)
  VALUES (${pgStr(j.news_key)}, ${pgStr(j.titel)}, ${pgStr(j.link || null)}, ${pgStr(j.quelle)},
          ${j.datum_iso ? pgStr(j.datum_iso) : 'NULL'}, 'pending', ${pgStr(j.beschreibung)}, ${pgStr(j.type)}, ${pgStr(j.matchGrund)}, ${pgJson(tickerArr)}, ${pgStr(j.content_hash)})
  ON CONFLICT (news_key) DO UPDATE SET
    preclassified_tickers = (
      SELECT COALESCE(jsonb_agg(DISTINCT elem), '[]'::jsonb)
      FROM jsonb_array_elements(trading.news_items.preclassified_tickers || EXCLUDED.preclassified_tickers) elem
    );`;
return { json: { ...j, sql } };

// Baut das news_batch-Array fuer die KI (id = echte trading.news_items.id,
// nicht mehr Array-Index -> robustere Rueckzuordnung, ersetzt die vorherige
// $getWorkflowStaticData-Zwischenspeicherung vollstaendig.
// FIX 2026-08-01 (Fehleranalyse D3/D4, kritisch): beschreibung war hier unbedingt auf ''
// gesetzt (der vom Vorfilter bereits sauber extrahierte RSS-Kurztext ging nie in die KI-
// Bewertung ein), type war konstant 'stock_news' obwohl der System-Prompt je nach Typ
// (stock_news/market_news/market_candidate) unterschiedlich instruiert. Beide Felder kommen
// jetzt aus der DB (siehe "DB: Faellige News laden", die description/preclassified_type
// mittlerweile mitliest), mit sicherem Fallback falls eine sehr alte Zeile vor D5 angelegt
// wurde und die neuen Spalten noch leer sind.
const items = $input.all().map(i => i.json);
const news_batch = items.map(j => ({
  id: j.id,
  type: j.type || 'stock_news',
  titel: j.titel,
  beschreibung: j.beschreibung || '',
  quelle: j.quelle
}));
return [{ json: { news_batch, _originals: items } }];

