// Robustes Parsing wie im Original, aber mit klarer retry/evaluated-
// Zuordnung statt eines ungefilterten Debug-Fallback-Datensatzes.
function getAiText(resp) {
  if (typeof resp === 'string') return resp;
  if (resp && Array.isArray(resp.output)) {
    const msg = resp.output.find(o => o.type === 'message');
    const part = msg && Array.isArray(msg.content) ? msg.content.find(c => c.type === 'output_text') : null;
    if (part && part.text) return part.text;
  }
  if (resp && resp.choices && resp.choices[0] && resp.choices[0].message) return resp.choices[0].message.content || '';
  if (resp && typeof resp.content === 'string') return resp.content;
  return JSON.stringify(resp || '');
}

function parseKiArray(text) {
  let t = String(text || '').trim();
  t = t.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  try {
    const p = JSON.parse(t);
    if (Array.isArray(p)) return p;
  } catch (e) {}
  const start = t.indexOf('[');
  const end = t.lastIndexOf(']');
  if (start >= 0 && end > start) {
    try {
      const p = JSON.parse(t.substring(start, end + 1));
      if (Array.isArray(p)) return p;
    } catch (e) {}
  }
  return null;
}

// D7-Muster (aus 03a uebernommen): fehlender/nicht-numerischer Wert wird NICHT
// stillschweigend zu 0, sondern bleibt null - "fehlt" und "ist echt 0" duerfen
// nicht verwechselt werden.
function confNum(v, min, max) {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.min(max, Math.max(min, n));
}

// D6: Wahrscheinlichkeitsverteilung nur uebernehmen, wenn alle drei Werte
// numerisch sind UND (fast) 1 ergeben - sonst lieber NULL als eine erfundene/
// inkonsistente Verteilung zu speichern (die CHECK-Constraints in sql/011
// wuerden eine falsche Summe ohnehin ablehnen, hier wird sie schon vorher
// erkannt statt den ganzen INSERT scheitern zu lassen).
function probTriple(pos, neg, neu) {
  const p = Number(pos), n = Number(neg), z = Number(neu);
  if (![p, n, z].every(Number.isFinite)) return { positive: null, negative: null, neutral: null };
  const sum = p + n + z;
  if (sum < 0.99 || sum > 1.01) return { positive: null, negative: null, neutral: null };
  return { positive: p, negative: n, neutral: z };
}

// D2: von der KI genannte Ticker duerfen nur solche sein, die tatsaechlich in
// der aktiven Watchlist stehen - eine halluzinierte oder veraltete
// Tickerzuordnung darf nicht unbemerkt in nachgelagerte Systeme (Report,
// Matrix-Alert) durchsickern.
let watchlistTickers = [];
try {
  watchlistTickers = $('DB: Watchlist fuer KI-Prompt laden').all().map(i => String(i.json.ticker || '').trim()).filter(Boolean);
} catch (e) {
  // Node nicht gefunden/nicht ausgefuehrt - leere Liste bedeutet: alle
  // gemeldeten Ticker werden unten als "nicht in Watchlist" verworfen. Das
  // ist absichtlich sicherheitsorientiert (kein ungeprueftes Durchreichen).
}
const watchlistSet = new Set(watchlistTickers);

const originals = $('Baue Batch-Payload').item.json._originals;
const rawText = getAiText($json);
const bewertungen = parseKiArray(rawText);

const results = [];

if (!bewertungen) {
  // Kompletter Parse-Fehlschlag: ALLE News dieses Batches auf retry setzen,
  // statt einen leeren Debug-Datensatz in die DB zu schreiben.
  for (const orig of originals) {
    results.push({ json: { _action: 'retry', _origin: orig, _error: 'KI-Antwort nicht als JSON-Array parsebar' } });
  }
  return results;
}

const byId = new Map(bewertungen.filter(x => x && x.id !== undefined).map(x => [String(x.id), x]));

for (const orig of originals) {
  const b = byId.get(String(orig.id));
  if (!b) {
    results.push({ json: { _action: 'retry', _origin: orig, _error: 'Keine Bewertung fuer diese News in der KI-Antwort enthalten' } });
    continue;
  }
  const relevant = b.relevanz && b.relevanz !== 'irrelevant';

  const gemeldeteTicker = Array.isArray(b.betroffene_ticker) ? b.betroffene_ticker : [];
  const betroffeneTickerGeprueft = gemeldeteTicker.filter(t => watchlistSet.has(String(t).trim()));
  const betroffeneTickerVerworfen = gemeldeteTicker.filter(t => !watchlistSet.has(String(t).trim()));

  const wahrscheinlichkeiten = probTriple(b.wahrscheinlichkeit_positiv, b.wahrscheinlichkeit_negativ, b.wahrscheinlichkeit_neutral);

  results.push({ json: {
    _action: 'persist',
    _origin: orig,
    news_id: orig.id,
    relevant,
    relevanz: b.relevanz || 'unbekannt',
    sentiment: b.sentiment || 'unklar',
    kurswirkung: b.kurswirkung || 'unklar',
    bezug: b.bezug || '',
    verwendung: b.verwendung || 'speichern',
    news_kategorie: ['quarterly_results','profit_warning','forecast_change','merger_acquisition','regulation','management_change','legal_dispute','product_news','macro','geopolitics','analyst_rating','other'].includes(b.news_kategorie) ? b.news_kategorie : 'other',
    score: b.score,
    dringlichkeit: b.dringlichkeit || 'beobachten',
    begruendung: b.begruendung || '',
    betroffene_ticker: betroffeneTickerGeprueft,
    betroffene_ticker_verworfen: betroffeneTickerVerworfen,
    wirkungsebene: b.wirkungsebene || 'unklar',
    wirkungsrichtung: ['positiv','negativ','neutral','unklar'].includes(b.wirkungsrichtung) ? b.wirkungsrichtung : 'unklar',
    wirkung_staerke: ['niedrig','mittel','hoch','unklar'].includes(b.wirkung_staerke) ? b.wirkung_staerke : 'unklar',
    begruendung_tickerbezug: b.begruendung_tickerbezug || '',
    relevance_confidence: confNum(b.relevanz_konfidenz, 0, 100),
    strength_confidence: confNum(b.staerke_konfidenz, 0, 100),
    data_quality_score: confNum(b.datenqualitaet_score, 0, 100),
    probability_positive: wahrscheinlichkeiten.positive,
    probability_negative: wahrscheinlichkeiten.negative,
    probability_neutral: wahrscheinlichkeiten.neutral,
    titel: orig.titel,
    link: orig.link
  } });
}

return results;

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { return v === null || v === undefined ? 'NULL' : (v ? 'TRUE' : 'FALSE'); }
function pgJson(v) { return `'` + JSON.stringify(v === undefined ? null : v).replace(/'/g, `''`) + `'::jsonb`; }
function pgArr(v) { return `'{` + (Array.isArray(v) ? v : []).map(x => String(x).replace(/"/g,'\\"')).join(',') + `}'`; }


const j = $json;
let sql;

if (j._action === 'persist') {
  const status = j.relevant ? 'evaluated' : 'discarded';
  sql = `INSERT INTO trading.news_assessments
    (news_id, relevant, wirkungsebene, betroffene_ticker_json, wirkungsrichtung, wirkung_staerke,
     sentiment, news_kategorie, usage_type, ticker_begruendung, wirkungs_begruendung, prompt_version,
     relevance_confidence, strength_confidence, data_quality_score,
     probability_positive, probability_negative, probability_neutral)
    VALUES (${pgNum(j.news_id)}, ${pgBool(j.relevant)}, ${pgStr(j.wirkungsebene)}, ${pgJson(j.betroffene_ticker)},
            ${pgStr(j.wirkungsrichtung)}, ${pgStr(j.wirkung_staerke)}, ${pgStr(j.sentiment)}, ${pgStr(j.news_kategorie)},
            ${pgStr(j.verwendung)},
            ${pgStr(j.begruendung_tickerbezug)}, ${pgStr(j.begruendung)}, ${pgStr('news-ingestion-v1')},
            ${pgNum(j.relevance_confidence)}, ${pgNum(j.strength_confidence)}, ${pgNum(j.data_quality_score)},
            ${pgNum(j.probability_positive)}, ${pgNum(j.probability_negative)}, ${pgNum(j.probability_neutral)});
   UPDATE trading.news_items SET status = ${pgStr(status)}, updated_at = now() WHERE id = ${pgNum(j.news_id)};`;
} else {
  const orig = j._origin || {};
  const retryCount = pgNum(orig.retry_count) === 'NULL' ? 0 : Number(orig.retry_count) + 1;
  const nextStatus = retryCount >= 5 ? 'failed' : 'retry';
  const backoffMinutes = retryCount * 15;
  sql = `UPDATE trading.news_items SET
    status = ${pgStr(nextStatus)},
    retry_count = ${pgNum(retryCount)},
    last_error = ${pgStr(j._error)},
    last_attempt_at = now(),
    next_retry_at = now() + interval '${backoffMinutes} minutes',
    updated_at = now()
   WHERE id = ${pgNum(orig.id)};`;
}

return { json: { ...j, sql } };

const j = $input.item.json;
if (j.error) {
  const msg = j.message || (j.error && j.error.message) || (j.error && j.error.description) || j.error;
  throw new Error(typeof msg === 'string' ? msg : JSON.stringify(msg));
}
return $input.item;

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const relevanz = String($json.relevanz || 'unbekannt').toUpperCase();
const titel = $json.titel || 'Ohne Titel';
const type = $json.type || 'unbekannt';
const ticker = $json.ticker || '';
const name = $json.name || '';
const bezug = $json.bezug || 'unklar';
const sentiment = $json.sentiment || 'unklar';
const kurswirkung = $json.kurswirkung || 'unklar';
const score = $json.score ?? '';
const dringlichkeit = $json.dringlichkeit || 'beobachten';
const begruendung = $json.begruendung || '';
const link = $json.link || '';

const body =
`🚨 Aktien-Radar: ${relevanz}

${titel}

Typ: ${type}
Ticker: ${ticker}
Name: ${name}
Bezug: ${bezug}
Sentiment: ${sentiment}
Kurswirkung: ${kurswirkung}
Score: ${score}
Dringlichkeit: ${dringlichkeit}

${begruendung}

${link}`;

const formatted_body =
`<b>🚨 Aktien-Radar: ${esc(relevanz)}</b><br>
<b>${esc(titel)}</b><br><br>
<b>Typ:</b> ${esc(type)}<br>
<b>Ticker:</b> ${esc(ticker)}<br>
<b>Name:</b> ${esc(name)}<br>
<b>Bezug:</b> ${esc(bezug)}<br>
<b>Sentiment:</b> ${esc(sentiment)}<br>
<b>Kurswirkung:</b> ${esc(kurswirkung)}<br>
<b>Score:</b> ${esc(score)}<br>
<b>Dringlichkeit:</b> ${esc(dringlichkeit)}<br><br>
<i>${esc(begruendung)}</i><br><br>
${link ? `<a href="${esc(link)}">Quelle öffnen</a>` : ''}`;

return {
  json: {
    ...$json,
    matrixTxnId: `${$execution.id}-news-${$itemIndex}-${Date.now()}`,
    matrixPayload: {
      msgtype: 'm.text',
      format: 'org.matrix.custom.html',
      body,
      formatted_body
    }
  }
};

// FIX (2026-07-22): "KI: Nachricht bewerten" ist der einzige Agent in diesem
// Projekt, der nie in trading.agent_runs protokolliert wird - er erscheint
// deshalb nie in der Status-Uebersicht ("Agentenlaeufe"), obwohl er stuendlich
// laeuft. Ein API-Call bewertet einen ganzen Batch (bis zu 15 News), daher
// hier EINE zusammenfassende Zeile pro Batch-Aufruf statt einer Zeile pro
// Einzel-News (konsistent mit dem "ein Modellaufruf = eine Zeile"-Muster in
// 03a/09/10, nur auf Batch-Ebene).
function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

const items = $input.all().map(i => i.json);
const total = items.length;
const persistCount = items.filter(i => i._action === 'persist').length;
const retryCount = total - persistCount;
const status = total === 0 ? 'skipped' : (retryCount === 0 ? 'success' : (persistCount === 0 ? 'failed' : 'partial_failure'));
const newsIds = items.map(i => i.news_id ?? (i._origin && i._origin.id)).filter(v => v !== undefined && v !== null).join(',');
const errorMessage = retryCount > 0
  ? [...new Set(items.filter(i => i._action !== 'persist').map(i => i._error).filter(Boolean))].join(' | ') || null
  : null;

const sql = `INSERT INTO trading.agent_runs
  (run_id, agent_name, agent_role, model_name, prompt_version, input_reference, output_reference, status, error_message, started_at, finished_at)
  VALUES (${pgStr('news-bewertung-' + getBusinessDate() + '-' + Date.now())}, 'news-bewertung-agent', 'bewertung',
          'gpt-5.4-mini', 'news-ingestion-v1', ${pgStr('news_ids=' + newsIds)}, ${pgStr('persist=' + persistCount + ',retry=' + retryCount)},
          ${pgStr(status)}, ${pgStr(errorMessage)}, now(), now());`;

return [{ json: { sql } }];
